import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro — arena legal-move enumeration + the first construction depth probe","description":"","frontmatter":{"title":"Retro — arena legal-move enumeration + the first construction depth probe","type":"retro","date":"2026-10-14T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/arena-depth.md","filePath":"vendored/graphopt/project/retros/arena-depth.md"}`),a={name:`graphopt/project/retros/arena-depth.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-—-arena-legal-move-enumeration-the-first-construction-depth-probe" tabindex="-1">Retro — arena legal-move enumeration + the first construction depth probe <a class="header-anchor" href="#retro-—-arena-legal-move-enumeration-the-first-construction-depth-probe" aria-label="Permalink to “Retro — arena legal-move enumeration + the first construction depth probe”">​</a></h1><p>Plan 0020 phase 2. <code>legal_actions(state)</code> enumerates the live construction moves; <code>depth_probe</code> plays the three baseline players on the real board (<code>python -m mlopt_discovery.arena</code>).</p><h2 id="the-board-is-large" tabindex="-1">The board is large <a class="header-anchor" href="#the-board-is-large" aria-label="Permalink to “The board is large”">​</a></h2><p>Legal move count at episode start: <strong>~143k–152k</strong>, growing to ~187k after an episode (each stored object adds relax/specialize moves). The action space is combinatorial — composite spellings × kernels × carrier bases × premise pairs × guard clauses × metavariable pins. This is not a scheduler with four arms; it is a deep board.</p><h2 id="the-probe-2-episodes-×-budget-8-seed-0" tabindex="-1">The probe (2 episodes × budget 8, seed 0) <a class="header-anchor" href="#the-probe-2-episodes-×-budget-8-seed-0" aria-label="Permalink to “The probe (2 episodes × budget 8, seed 0)”">​</a></h2><table tabindex="0"><thead><tr><th>player</th><th>steps</th><th>usable</th><th>holdout fires</th><th>holdout paid</th><th>reward</th></tr></thead><tbody><tr><td>fixed</td><td>5/5</td><td>0</td><td>8 / 0</td><td><strong>2 / 0</strong></td><td>23.6 / 17.0</td></tr><tr><td>random</td><td>8/8</td><td>0</td><td>2 / 0</td><td>0 / 0</td><td>24.4 / 24.0</td></tr><tr><td>greedy</td><td>8/8</td><td>0</td><td>0 / 0</td><td>0 / 0</td><td>24.0 / 24.0</td></tr></tbody></table><h2 id="honest-read" tabindex="-1">Honest read <a class="header-anchor" href="#honest-read" aria-label="Permalink to “Honest read”">​</a></h2><ul><li><strong>Move choice matters</strong> — the authored playbook&#39;s <code>compose</code> step (<code>comm_mul ∘ silu_fold</code> → <code>silu_swapped</code>) pays 2 on holdout; greedy pays nothing. The payoff surface is not flat.</li><li><strong>Nobody mints <code>usable</code> in 8 moves</strong> — the easy constructions are already in the store; admitting a new object takes more horizon than the probe&#39;s budget.</li><li><strong>Reward is stage-clear-dominated</strong> — random/greedy score ~24 by clearing 3 stages per applied move; holdout pays are the signal that separates them.</li><li>Episode variance is real (fixed ep1: 0 fires) — different split seeds move the holdout.</li></ul><h2 id="what-s-wired" tabindex="-1">What&#39;s wired <a class="header-anchor" href="#what-s-wired" aria-label="Permalink to “What&#39;s wired”">​</a></h2><p><code>relax_guard</code> / <code>specialize</code> are registered arena actions with <code>Action.relax_guard</code>/<code>Action.specialize</code> classmethods; <code>ObjectView</code> exposes <code>cond_clauses</code>/<code>leaf_metavars</code>/<code>attr_metavars</code> (the object&#39;s own stored data — safe for the player); <code>legal_actions</code> enumerates per-clause relax moves and per-metavar pin moves over the <code>lawdata.SPECIALIZE_{SCALARS,AXES}</code> banks. The pin banks are data — a richer pin is a data change, not code.</p><h2 id="the-24-step-probe-3-episodes-×-budget-24-seed-0" tabindex="-1">The 24-step probe (3 episodes × budget 24, seed 0) <a class="header-anchor" href="#the-24-step-probe-3-episodes-×-budget-24-seed-0" aria-label="Permalink to “The 24-step probe (3 episodes × budget 24, seed 0)”">​</a></h2><table tabindex="0"><thead><tr><th>player</th><th>usable</th><th>holdout fires</th><th>holdout paid</th><th>reward</th></tr></thead><tbody><tr><td>fixed</td><td>0</td><td>8/0/0</td><td><strong>2/0/0</strong></td><td>23.6/17/17</td></tr><tr><td>random</td><td>0</td><td>2/2/1</td><td>0/1/0</td><td>66/72/66</td></tr><tr><td>greedy</td><td>0</td><td>0/0/0</td><td>0/0/0</td><td>72/72/72</td></tr></tbody></table><p>Two findings:</p><ul><li><strong>Nobody reaches <code>usable</code> in 24 moves.</strong> The admitted-object bar needs longer horizons or guided play — random and greedy churn through applied-but-unproductive constructions.</li><li><strong>The reward is stage-clear-dominated.</strong> Greedy maxes reward (72.0) with <em>zero</em> holdout yield — <code>stages_cleared + 0.2·fires + 2·paid</code> lets three cleared stages outscore a paying object until it admits. <strong>Fixed as data</strong>: <code>lawdata.ARENA_REWARD</code> is now <code>stage=0.1, usable=10, fire=0.5, paid=5</code> — the objective (admitted, paying objects) outweighs a full budget of churn (24 × ~0.3 ≈ 7 &lt; one usable&#39;s 10). Under the old weights the same fixed episode scores 23.6; under the new, ~15–16 — still the only paying line, now correctly top of the board.</li></ul><h2 id="verdict-for-plan-0021" tabindex="-1">Verdict for plan 0021 <a class="header-anchor" href="#verdict-for-plan-0021" aria-label="Permalink to “Verdict for plan 0021”">​</a></h2><p>The construction board is <strong>deep enough to measure</strong>: large action space, payoff differences between players, honest holdout. The board&#39;s depth for a <em>learned</em> player is the open question — the reward no longer rewards churn, so a longer-horizon probe (or a learned policy over the ~150k-move set) is the next measurement.</p><h2 id="the-cheap-board-long-horizon-probe" tabindex="-1">The cheap board / long horizon probe <a class="header-anchor" href="#the-cheap-board-long-horizon-probe" aria-label="Permalink to “The cheap board / long horizon probe”">​</a></h2><p>The real board&#39;s ~5-8 s/step (a full gauntlet over 261 working terms plus a 50-case probe) made the depth question unmeasurable: 24 steps cost ~1 h. <code>make_arena</code> now takes <code>max_cases</code> / <code>max_holdout</code> — seeded sha256-ranked subsamples drawn <em>after</em> the honest split, so the holdout stays real-only and probe-eligible and can never leak back into working. At <code>max_cases=24, max_holdout=12</code> the board has ~35k-51k legal moves, a deep step costs ~1 s, and the probe below (5 episodes x budget 60, four arms) ran in <strong>~15 min</strong>.</p><p>The probe (<code>max_cases=24</code>, <code>max_holdout=12</code>, seed 0, budget 60):</p><table tabindex="0"><thead><tr><th>player</th><th>steps</th><th>usable</th><th>holdout fires</th><th>holdout paid</th><th>reward</th></tr></thead><tbody><tr><td>fixed</td><td>6-7/episode (drains)</td><td><strong>1/0/0/0/1</strong></td><td>4/0/0/0/4</td><td>1/0/0/0/1</td><td>19.3/2.3/2.0/2.3/19.3</td></tr><tr><td>random</td><td>60</td><td>0</td><td>0/1/1/5/0</td><td>0/0/0/2/0</td><td>14-24</td></tr><tr><td>greedy</td><td>60</td><td>0</td><td>0</td><td>0</td><td>18.0 all</td></tr><tr><td>heuristic</td><td>60</td><td>0</td><td>0</td><td>0</td><td>~17.8 all</td></tr></tbody></table><p>Three findings:</p><ul><li><strong><code>usable</code> is reachable but only through authored knowledge.</strong> The fixed playbook admits the aff-step lift in 2 of 5 episodes (the subsample decides whether the working set keeps a measuring site and the 12-case probe keeps a paying one). No enumerated-frontier arm — random, greedy, or the new heuristic — mints a usable object in 300 moves.</li><li><strong>Move ordering separates on <em>depth</em>, not yet on yield.</strong> The heuristic (<code>lawdata.ARENA_MOVE_ORDER</code>: auto_cond -&gt; compose -&gt; relax -&gt; fold -&gt; ingest -&gt; specialize -&gt; lift, each move spent once) gets ~29% of its plays past truth+novelty vs ~2% random and 0% greedy — but converts none to holdout fires. Its episode is 34 composes + 26 auto_conds: the preference walk <em>never drains the top classes</em>, so at this budget it never reaches the fold/lift mass where firing objects live. A ranked order is a frontier policy; the tail ranks are unreachable when the head class has ~14k members.</li><li><strong>The bottleneck is <code>truth</code>, then <code>typed-pay</code>.</strong> Stage-failure aggregates over the run: random <code>truth</code> 199 / <code>full-data</code> 72 / <code>declined</code> 24 / <code>typed-pay</code> 5; greedy <code>truth</code> 300 (every largest- spec fold is a false equality); heuristic <code>truth</code> 154 / <code>typed-pay</code> 86 / <code>declined</code> 60. <code>truth</code> kills most minted constructions — the board&#39;s constructions are mostly <em>false</em> equalities, not unmeasured ones. For deeper arms the wall moves to <code>typed-pay</code>: true, novel objects that never fire or pay on the probe (12 holdout cases is a small target — a <code>usable</code> needs fires&gt;0 <em>and</em> paid&gt;0 <em>there</em>). <code>full-data</code> (72, all random) is the compose-products-drop-check-hooks class.</li></ul><p>Two infrastructure findings the run surfaced:</p><ul><li><strong>Cert materialization gap.</strong> An enumerated <code>compose</code> whose specialize map leaves an attr metavariable free (the <code>sdpa_fold_*</code> family&#39;s <code>SC</code> — <code>INSTANCE_ATTR_DEFAULTS</code> covers TD/SD/DP/DT but not <code>SC</code>) produced a rule <code>lemma_cert.materialize</code> raised <code>KeyError</code> on — an episode-killing crash. <code>Arena.step</code> now converts referee-side failures into an honest <code>applied=False</code> refusal (<code>referee declined: ...</code> in the note); ~1 in 60 random moves hits it.</li><li><strong>Cheap-board auto-cond starvation.</strong> All 12 heuristic declines per episode are <code>auto_cond</code> refusals — &quot;no equal site in the measured domain&quot;: a 24-case working corpus measures too few equal sites for the guard synth to cover. The rescue class is weaker on the small board by construction.</li></ul><p>Verdict, sharpened: the board is deep-but-winnable — <code>usable</code> is <em>reachable</em>, not far-away-invisible; the blocker is that enumerated constructions are mostly false (<code>truth</code>) and the true ones mostly don&#39;t pay on the probe (<code>typed-pay</code>). A learned player&#39;s edge, if any, is in <em>targeting</em> — picking constructions that fire on real workloads — which is exactly what the frontier arms cannot do.</p><h2 id="post-rebalance-probe-cheap-board-3-eps-×-budget-40" tabindex="-1">Post-rebalance probe (cheap board, 3 eps × budget 40) <a class="header-anchor" href="#post-rebalance-probe-cheap-board-3-eps-×-budget-40" aria-label="Permalink to “Post-rebalance probe (cheap board, 3 eps × budget 40)”">​</a></h2><p>Under <code>ARENA_REWARD</code> = <code>stage=0.1, usable=10, fire=0.5, paid=5</code>:</p><table tabindex="0"><thead><tr><th>player</th><th>usable</th><th>fires</th><th>paid</th><th>reward</th></tr></thead><tbody><tr><td>fixed</td><td><strong>1/0/0</strong></td><td>4/0/0</td><td>1/0/0</td><td><strong>19.3</strong>/2.3/2.0</td></tr><tr><td>random</td><td>0</td><td>0/1/1</td><td>0</td><td>9.7–10.7</td></tr><tr><td>greedy</td><td>0</td><td>0</td><td>0</td><td>12.0</td></tr><tr><td>heuristic</td><td>0</td><td>0</td><td>0</td><td>9.7</td></tr></tbody></table><p>The inversion is fixed: the episode that mints a usable, paying object tops the board (19.3), churn policies score below it. Stage-failure aggregate: <code>truth</code> kills most constructions (72–120/player), then <code>typed-pay</code>/<code>novelty</code>/<code>full-data</code>.</p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};